 video=COMFY/'input'/('street_'+id+f'_native_v{a.revision}.mp4');subprocess.run(['ffmpeg','-hide_banner','-loglevel','error','-y','-framerate',str(meta['frames']/2.5),'-i',str(prepared/'frame_%04d.png'),'-vf','fps=24','-c:v','libx264','-pix_fmt','yuv420p','-crf','16',str(video)],check=True)
